-- composition of rule kernels L:eliminate_cross_join x L:extract_equijoin_predicate (datafusion), template union
SELECT count(*) FROM (SELECT 1 AS k FROM (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2) AS ka UNION ALL SELECT 2 AS k FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb) AS u;
-- pgfuzz:check kernel:union SELECT (SELECT count(*) FROM (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2) AS ka) + (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0 FROM (t4 AS a1 JOIN t4 AS a2 ON (a1.c0 = a2.c0)) GROUP BY a1.c0, a2.c0 UNION ALL (SELECT '2024-02-29'::date AS c0 UNION SELECT '1999-12-31'::date AS c0)) AS kb)
